{
  "references": [
    {
      "id": "R1",
      "summary_ko": "인물이 영상 대부분에서 고뇌하며 아래나 옆을 보는 대신 위와 앞을 바라보고 있으며, 공식적인 분위기인지 불분명하고 모호하게 정돈된 느낌임",
      "claims": [
        {
          "id": "R1.S1",
          "evidence": "He looks up and ahead instead of contemplatively down or to the side for most of the video",
          "symptom_ko": "영상 대부분에서 고뇌에 찬 모습으로 아래나 옆을 내려다보지 않고 위와 앞을 바라봄",
          "role": "complaint"
        },
        {
          "id": "R1.S2",
          "evidence": "also it's unclear that it's a formal setting it's more ambiguosly clean feeling",
          "symptom_ko": "격식 있는 장소인지 불분명하고 모호하게 깔끔한 느낌에 가까움",
          "role": "complaint"
        }
      ]
    },
    {
      "id": "R2",
      "summary_ko": "목 부분이 이상하게 변형되어 생성되며, 울대뼈(아담스 애플) 유무가 불확실한 것처럼 보임.",
      "claims": [
        {
          "id": "R2.S1",
          "evidence": "His neck shifts somewhat oddly in how it's generated? Maybe it can't decide if he has an adam's apple or not?",
          "symptom_ko": "목이 비정상적으로 움직이거나 변형되며 울대뼈의 존재 여부가 불안정함",
          "role": "complaint"
        }
      ]
    }
  ],
  "candidates": [],
  "pairs": []
}

